import sys

def main():
    word = sys.stdin.readline().strip()
    if not word:
        print(0)
        return

    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    count = 0

    for char in word:
        if char in vowels:
            count += 1

    print(count)

if __name__ == "__main__":
    main()
